import { createMeetingType, upsertAvailabilityRule } from '@projexlight/sdk-scheduling';

const meetingType = await createMeetingType({
  tenant_id, host_persona_id: hostId,
  name: 'Intro Call', slug: 'intro-call', duration_minutes: 30,
  buffer_before_minutes: 5, buffer_after_minutes: 5, location_type: 'video',
});

// Monday-Friday 09:00-17:00 New York time, 30-minute slots.
for (const weekday of [1, 2, 3, 4, 5]) {
  await upsertAvailabilityRule({
    tenant_id, host_persona_id: hostId, weekday,
    start_time: '09:00', end_time: '17:00',
    timezone: 'America/New_York', slot_interval_minutes: 30,
  });
}

// 1) Host creates the shareable link (authenticated).
import { createSchedulingLink } from '@projexlight/sdk-scheduling';
const link = await createSchedulingLink({
  tenant_id, host_persona_id: hostId, slug: 'meet-jane',
  meeting_type_id: meetingType.meeting_type_id, max_days_ahead: 30, min_notice_minutes: 60,
});

// 2) Visitor (anonymous) fetches slots and books one via the public routes.
const res = await fetch('/api/scheduling/public/links/meet-jane/book', {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: JSON.stringify({
    start_time: '2026-08-01T15:00:00Z',
    invitee_name: 'Sam Prospect', invitee_email: 'sam@example.com',
    timezone: 'America/New_York',
  }),
});
const { data } = await res.json(); // { appointment, public_token }

import { cancelByToken } from '@projexlight/sdk-scheduling';

const appointment = await cancelByToken(publicToken, 'Something came up');
if (!appointment) {
  // Unknown token: indistinguishable 404 — never reveal whether the
  // token was wrong or the appointment merely absent.
  throw new Error('NotFound');
}
// appointment.status === 'cancelled'; cancelled_at is stamped and the
// host's slot is freed for rebooking.
